<?php require __DIR__.'/includes/bootstrap.php';if(user())go('account.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$name||!$email||strlen($pw)<10)$err='Enter a valid name/email and password of at least 10 characters.';else{try{$s=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$s->execute([$name,strtolower($email),password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];go('account.php');}catch(Throwable $e){$err='That email may already be registered.';}}}$pageTitle='Create account';require __DIR__.'/includes/header.php';?><section class="auth"><div><small class="eyebrow">A PLACE OF YOUR OWN</small><h1>Good to have<br><em>you here.</em></h1><p>Create an account to keep your orders and details together.</p></div><form method="post" class="auth-card"><?=csrf()?><h2>Create account</h2><?php if($err):?><p class="error"><?=$err?></p><?php endif;?><label>Your name<input name="name" required></label><label>Email address<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="10" required><small>At least 10 characters.</small></label><button class="btn dark full">Create my account ↗</button><p>Already have an account? <a href="login.php">Sign in</a></p></form></section><?php require __DIR__.'/includes/footer.php';?>
